        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):

    def gcd(a, b):
        return math.gcd(a, b)

    def get_square_free_part(n):
        if n <= 0:
            return n
        sf = 1
        i = 2
        while i * i <= n:
            count = 0
            while n % i == 0:
                count += 1
                n //= i
            if count % 2 == 1:
                sf *= i
            i += 1
        if n > 1:
            sf *= n
        return sf

    for _ in range(100): # Retry loop to find valid parameters
        p, q = rng.choice([(1, 2), (2, 3), (3, 4), (5, 12), (8, 15)])
        if rng.random() < 0.5:
            p, q = q, p

        n = rng.randint(3, 10)
        possible_m = [i for i in range(1, n) if gcd(i, n) == 1]
        if not possible_m:
            continue
        m = rng.choice(possible_m)

        if n**2 - m**2 == 0:
            continue

        D_full = (p**2 + q**2) * (n**2 - m**2)
        N_full = 2 * m**2

        common_divisor = gcd(N_full, D_full)
        N_reduced = N_full // common_divisor
        D_reduced = D_full // common_divisor

        if D_reduced <= 0:
            continue

        k1 = get_square_free_part(D_reduced)
        k2_sq = D_reduced // k1
        k2 = int(math.sqrt(k2_sq))

        if k2*k2 != k2_sq:
            continue

        A_min = k1 * k2
        if A_min == 0:
            continue

        target_area = rng.randint(200, 1000)

        if N_reduced * k1 == 0:
            continue

        c_float = (target_area / (N_reduced * k1))**0.5
        c = rng.choice([max(1, int(c_float)), int(c_float) + 1])
        if c == 0: c = 1

        A = c * A_min

        area_num = N_full * A**2
        area_den = D_full

        if area_num % area_den != 0:
            continue

        area = area_num // area_den

        if area < 100 or area > 2000 or A < 10:
            continue

        return {
            "p": p,
            "q": q,
            "n": n,
            "m": m,
            "A": A
        }

    return {"p": 3, "q": 4, "n": 5, "m": 3, "A": 100}

